/*
 * A191107  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-2 and 3x+1 are in a.
 * https://oeis.org/A191107
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the base‑3 value of the binary representation of (2*n-1)
 *            (i.e., all numbers that in base 3 use only digits 0 or 1 and end
 *            with 1)
 * Range:     u8 n <= 19, u16 n <= 640, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* n >= 1 */
    idx_t t = n - 1;          /* binary representation of (n-1) */
    seq_t result = 1;         /* accounts for the final '1' in base‑3 */
    seq_t power  = 3;         /* 3^1 for the next digit */

    while (t)
    {
        if (t & 1)
            result += power;  /* add next base‑3 place if bit is 1 */
        power *= 3;           /* advance to next power of 3 */
        t >>= 1;
    }
    return result;
}
